def rescue_route(board, start, goal):
    directions = ["up", "right", "down", "left"]
    offsets = [[0, -1], [1, 0], [0, 1], [-1, 0]]
    width = len(board[0])
    height = len(board)
    cells = width * height
    queue = [[start[0], start[1], False, []]]
    seen = {start[1] * width + start[0]: True}
    while len(queue) > 0:
        cell = queue.pop(0)
        if [cell[0], cell[1]] == goal:
            return cell[3]
        for index in range(4):
            x = cell[0] + offsets[index][0]
            y = cell[1] + offsets[index][1]
            if x < 0 or x >= width or y < 0 or y >= height:
                continue
            tile = board[y][x]
            if tile == "#" or (tile == "D" and not cell[2]):
                continue
            access = cell[2] or tile == "K"
            key = y * width + x
            if access:
                key += cells
            if key not in seen:
                seen[key] = True
                queue.append([x, y, access, cell[3] + [directions[index]]])
    return None
